"use strict";(self.webpackChunkrithmia=self.webpackChunkrithmia||[]).push([["7294"],{84(e,n,a){a.r(n),a.d(n,{metadata:()=>t,default:()=>c,frontMatter:()=>s,contentTitle:()=>l,toc:()=>h,assets:()=>o});var t=JSON.parse('{"id":"Setting/Cosmology/Inner Planes/Elemental Planes/overview","title":"Overview","description":"The elemental plane has gone through two main phases.","source":"@site/docs/Setting/Cosmology/Inner Planes/Elemental Planes/overview.md","sourceDirName":"Setting/Cosmology/Inner Planes/Elemental Planes","slug":"/Setting/Cosmology/Inner Planes/Elemental Planes/overview","permalink":"/Rithmia/docs/Setting/Cosmology/Inner Planes/Elemental Planes/overview","draft":false,"unlisted":false,"editUrl":"https://github.com/TravisH18/Rithmia/tree/main/docs/docs/Setting/Cosmology/Inner Planes/Elemental Planes/overview.md","tags":[],"version":"current","frontMatter":{},"sidebar":"settingSidebar","previous":{"title":"Dimension of Time","permalink":"/Rithmia/docs/Setting/Cosmology/Cognitive Planes/dimension-of-time"},"next":{"title":"Primal Plane (aka Fey Realm)","permalink":"/Rithmia/docs/Setting/Cosmology/Inner Planes/primal-plane"}}'),i=a(4848),r=a(8453);let s={},l="Overview",o={},h=[{value:"Elemental Chaos",id:"elemental-chaos",level:2},{value:"The Elemental War",id:"the-elemental-war",level:2},{value:"Elemental Energy Plane",id:"elemental-energy-plane",level:2},{value:"Design",id:"design",level:3},{value:"Subplanes (Planar partitions)",id:"subplanes-planar-partitions",level:2},{value:"Pure Partitions",id:"pure-partitions",level:2},{value:"The Plane of Earth",id:"the-plane-of-earth",level:3},{value:"The Plane of Air",id:"the-plane-of-air",level:3},{value:"The Plane of Fire",id:"the-plane-of-fire",level:3},{value:"The Plane of Water",id:"the-plane-of-water",level:3},{value:"Duo-partitions",id:"duo-partitions",level:2},{value:"Earth + Air Overlap:",id:"earth--air-overlap",level:3},{value:"Earth + Fire Overlap:",id:"earth--fire-overlap",level:3},{value:"Earth + Water Overlap:",id:"earth--water-overlap",level:3},{value:"Air and Fire Overlap:",id:"air-and-fire-overlap",level:3},{value:"Air and Water Overlap:",id:"air-and-water-overlap",level:3},{value:"Fire and Water Overlap:",id:"fire-and-water-overlap",level:3},{value:"Tri-partitions:",id:"tri-partitions",level:2},{value:"Earth, Air, and Fire Overlap (Solar, radiant, weak force):",id:"earth-air-and-fire-overlap-solar-radiant-weak-force",level:3},{value:"Earth, Air, and Water Overlap (Gravity):",id:"earth-air-and-water-overlap-gravity",level:3},{value:"Earth, Fire, and Water Overlap (Lunar, Strong Force) :",id:"earth-fire-and-water-overlap-lunar-strong-force-",level:3},{value:"Air, Fire, and Water Overlap (electromagnetic):",id:"air-fire-and-water-overlap-electromagnetic",level:3},{value:"Pandemonium",id:"pandemonium",level:2},{value:"The Luminous Nexus - Plane of Elemental Harmony, Apex Pandemonium (Time, Ether)",id:"the-luminous-nexus---plane-of-elemental-harmony-apex-pandemonium-time-ether",level:3},{value:"The Abyssal Crucible - Plane of Elemental Discord (Void, ether) Deep Pandemonium",id:"the-abyssal-crucible---plane-of-elemental-discord-void-ether-deep-pandemonium",level:3}];function d(e){let n={a:"a",em:"em",h1:"h1",h2:"h2",h3:"h3",header:"header",li:"li",p:"p",strong:"strong",ul:"ul",...(0,r.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(n.header,{children:(0,i.jsx)(n.h1,{id:"overview",children:"Overview"})}),"\n",(0,i.jsx)(n.p,{children:"The elemental plane has gone through two main phases."}),"\n",(0,i.jsx)(n.h2,{id:"elemental-chaos",children:"Elemental Chaos"}),"\n",(0,i.jsx)(n.p,{children:"The elemental chaos was its original forms once the primordials created as a biproduct of divine influence on the planet created life. They were deemed to dangerous and destructive and after a breif conflict were sealed away in a separate inner plane where they constantly battled eachother, resulting in this plane becoming The Elemental Chaos."}),"\n",(0,i.jsx)(n.h2,{id:"the-elemental-war",children:"The Elemental War"}),"\n",(0,i.jsx)(n.p,{children:"Before her sundering The Allmother was in command of all the elements as part of her Domain. With her loss of strength and sanity due to splitting herself in half these powers had gone ungoverned for millenia. War broke out as several heralds all at once appeared and declared the victors and four strongest contestants of this new war would be crowned as the heads of a new (lesser deity) pantheon known as the Elemental Pantheon. Therefore, the Elemental War began. Afterwards some Genies claiming they should have not had to fight for the right to the pantheon were very bitter at the loss of this war and retreated to the new organized version of the Elemental Chaos now deemed the Elemental Energy Plane in order to get stronger, strategize, and craft new powerful items. Genies have conquered large portions of these lands as their own as the only draconic residents are the new heads of the elemental pantheon and their families / chosen mortals. With this the retreat Genies often left behind cities they were in charge of and the populous now have mixed feelings about genies. Genies were known to leave treasure hoards guarded by mummies behind."}),"\n",(0,i.jsx)(n.h2,{id:"elemental-energy-plane",children:"Elemental Energy Plane"}),"\n",(0,i.jsx)(n.p,{children:"During the Age of Elemental Lords the Genie's, who were spawned from elemental chaos as sentient elemental infused souls, sought to claim the title of Conquerers of the Elements and cement themselves at the top of this age by defeating and taming the primordials in the elemental chaos and reshaping it to their liking. This took decades and cost many lives but the result was no more chaos. They created the Elemental Energy Plane (Altaaqat Al'awalia)."}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.em,{children:"Note"}),": Genies are elemental infused souls bound to the EEP, like devils are bound to the Nine Hells, where as Genasi are partially elemental infused mortal souls. Meaning their souls may have ties to an element strong enough that on the River of Souls they may be drawn to and reincarnate as full Genies."]}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.em,{children:(0,i.jsx)(n.strong,{children:"Dragons in the EEP"})}),": Due to their elemental affinity Dragons are able to draw on the power of Elemental Nexus's across the plane. while their souls may not be tied to the plane they are able to harness and consume the power of the plane to great effect. It is rumored a pilgramage to their align elemental subplane is required to ascend to Greatwyrm status."]}),"\n",(0,i.jsx)(n.h3,{id:"design",children:"Design"}),"\n",(0,i.jsxs)(n.p,{children:["The EEP is a globe made up of two different 4-way venn diagrams. The north and south poles where all four elements overlap are the ends of a massive, planar sized magic core known as the ",(0,i.jsx)(n.em,{children:"Pandemonium Stone"})," and item said to be able to harness and enhance any elemental power. It has two poles meaning where the subplanes (",(0,i.jsx)(n.em,{children:"described below"}),") are affected by which end of the ",(0,i.jsx)(n.em,{children:"Pandemonium Stone"})," they are nearest to."]}),"\n",(0,i.jsx)(n.h2,{id:"subplanes-planar-partitions",children:"Subplanes (Planar partitions)"}),"\n",(0,i.jsx)(n.p,{children:"The two overlaping 4-way venn diagrams create an imense number of partitions in this plane where various different overlaps of the pure elements of earth, air, fire, and water create all kinds of different planes. Throughout this section we will describe the various planes, the landscape, inhabitants, unique environemntal or magic effects, and some quests, plot hooks, or the purpose of the plane itself."}),"\n",(0,i.jsx)(n.h2,{id:"pure-partitions",children:"Pure Partitions"}),"\n",(0,i.jsx)(n.h3,{id:"the-plane-of-earth",children:"The Plane of Earth"}),"\n",(0,i.jsx)(n.p,{children:"Home of the Dao"}),"\n",(0,i.jsx)(n.h3,{id:"the-plane-of-air",children:"The Plane of Air"}),"\n",(0,i.jsx)(n.p,{children:"Home of the Djinni"}),"\n",(0,i.jsx)(n.h3,{id:"the-plane-of-fire",children:"The Plane of Fire"}),"\n",(0,i.jsx)(n.p,{children:"Home of the Effreti"}),"\n",(0,i.jsx)(n.h3,{id:"the-plane-of-water",children:"The Plane of Water"}),"\n",(0,i.jsx)(n.p,{children:"Home of the Marid"}),"\n",(0,i.jsx)(n.h2,{id:"duo-partitions",children:"Duo-partitions"}),"\n",(0,i.jsx)(n.p,{children:"Where two of the above pure partions overlap to create different elements. A symbol (+) / (-) shows which side of the global plane it is on. Positive (+) being on the north side of the plane and negative (-) being on the south side of the plane"}),"\n",(0,i.jsx)(n.h3,{id:"earth--air-overlap",children:"Earth + Air Overlap:"}),"\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsxs)(n.li,{children:["\n",(0,i.jsx)(n.p,{children:"(+) Leviterra, The Plane of Magnetism: This plane is a realm where floating islands made of earth and stone drift through the sky. It's a place of serene beauty, with lush forests and majestic mountains suspended in the air. Winged creatures and air elementals inhabit this realm, and gravity works differently here."}),"\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsxs)(n.li,{children:["Creatures:","\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsx)(n.li,{children:"Magnetic Mantas: These creatures are similar to manta rays, but they have the ability to generate and manipulate magnetic fields. They use these fields to navigate through the air currents around the floating islands and to communicate with other creatures."}),"\n",(0,i.jsx)(n.li,{children:"Magnetic Minnows: These small fish-like creatures are attracted to magnetic fields and can often be found swimming in the crystalline rivers and waterfalls that flow from the islands."}),"\n",(0,i.jsx)(n.li,{children:"Aeromagnetic Anomalies: These creatures are small, insect-like creatures that have the ability to generate powerful magnetic fields. They use these fields to levitate and move through the air currents around the floating islands."}),"\n"]}),"\n"]}),"\n"]}),"\n"]}),"\n",(0,i.jsxs)(n.li,{children:["\n",(0,i.jsx)(n.p,{children:"(-) Dustlorn, The Plane of Sandstorm:  This is a desolate and barren wasteland where storms of razor-sharp earth and swirling winds dominate. The landscape is marked by endless canyons and dust storms, and it's a harsh environment for those who venture here."}),"\n"]}),"\n"]}),"\n",(0,i.jsx)(n.h3,{id:"earth--fire-overlap",children:"Earth + Fire Overlap:"}),"\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsxs)(n.li,{children:["\n",(0,i.jsx)(n.p,{children:"(+) Magmaforge, The plane of Lava: Magmaforge is a plane of fiery forges and molten rivers. The land is rich with precious minerals, and skilled blacksmiths craft incredible weapons and artifacts. The inhabitants are resilient beings, like lava golems and fire dwarves, who harness the power of both earth and fire."}),"\n"]}),"\n",(0,i.jsxs)(n.li,{children:["\n",(0,i.jsx)(n.p,{children:"(-) Ashen Wast plane of ash: Ashen Wastes is a scorched realm covered in smoldering volcanoes and rivers of flowing lava. The air is thick with smoke and ash, and it's a harsh, unforgiving place filled with destructive fire elementals."}),"\n"]}),"\n"]}),"\n",(0,i.jsx)(n.h3,{id:"earth--water-overlap",children:"Earth + Water Overlap:"}),"\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsxs)(n.li,{children:["\n",(0,i.jsx)(n.p,{children:"(+) Terraquatica The plane of wood: Terraquatica is a paradise of lush forests and crystal-clear lakes. The earth and water intertwine, giving rise to vibrant flora and aquatic creatures. Nymphs and dryads coexist with water elementals, and it's a realm of natural beauty and harmony."}),"\n"]}),"\n",(0,i.jsxs)(n.li,{children:["\n",(0,i.jsx)(n.p,{children:"(-) Murkmire, The plane of mud: Murkmire is a swampy, marshland where stagnant water mixes with decaying vegetation. It's a grim place, filled with treacherous bogs, monstrous creatures, and eerie, whispering spirits."}),"\n"]}),"\n"]}),"\n",(0,i.jsx)(n.h3,{id:"air-and-fire-overlap",children:"Air and Fire Overlap:"}),"\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsxs)(n.li,{children:["\n",(0,i.jsx)(n.p,{children:"(+) Zephyrflame, The plane of combustion: Zephyrflame is a realm of perpetual dawn, where fiery winds carry luminous embers through the sky. It's a land of warmth and gentle breezes, inhabited by graceful phoenixes, sylphs, and fire-dancing beings. It's a place of inspiration and creativity."}),"\n"]}),"\n",(0,i.jsxs)(n.li,{children:["\n",(0,i.jsx)(n.p,{children:"(-) Infernal Gale, The plane of smoke: Infernal Gale is a turbulent and dangerous plane where raging firestorms and hurricane-like winds create a chaotic, destructive environment. Fire elementals and volatile air spirits battle for supremacy in this unpredictable and perilous realm."}),"\n"]}),"\n"]}),"\n",(0,i.jsx)(n.h3,{id:"air-and-water-overlap",children:"Air and Water Overlap:"}),"\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsxs)(n.li,{children:["\n",(0,i.jsx)(n.p,{children:"(+) Celestiaquas, Plane of ice: Celestiaquas is a realm of serene, floating islands where the air and water merge seamlessly. It's a place of peace and tranquility, where merfolk and cloud-dwelling beings coexist. The skies are filled with radiant rainbows, and the seas are frozen as cold misty air freezes the water as it falls off the snowy islands."}),"\n"]}),"\n",(0,i.jsxs)(n.li,{children:["\n",(0,i.jsx)(n.p,{children:"(-) Tempest Depths, Plane of storm: Tempest Depths is a realm of endless storms, with violent tornadoes, typhoons, and water spouts. It's an unforgiving environment for those who dare to venture here, inhabited by fearsome water elementals and stormy spirits."}),"\n"]}),"\n"]}),"\n",(0,i.jsx)(n.h3,{id:"fire-and-water-overlap",children:"Fire and Water Overlap:"}),"\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsxs)(n.li,{children:["\n",(0,i.jsx)(n.p,{children:"(+) Aquablaze Haven, The plane of steam: Aquablaze Haven is a unique world where water and fire exist in harmony. The landscape features mesmerizing geysers, steamy jungles, and peaceful hot springs. Inhabitants are both fire-wielding aquatic creatures and water-resistant fire beings."}),"\n"]}),"\n",(0,i.jsxs)(n.li,{children:["\n",(0,i.jsx)(n.p,{children:"(-) Vapor Bayou, The plane of mist: Steamscorch Wastes is a place of hot uncomfortable humid hot swamps blanketed in a layer of mist. The ground is rough obsidian like stone. Small vents and searing geysers spout out through cracks in the ground. The land is barren and unforgiving, inhabited by volatile steam elementals and scalding lava creatures."}),"\n"]}),"\n"]}),"\n",(0,i.jsx)(n.h2,{id:"tri-partitions",children:"Tri-partitions:"}),"\n",(0,i.jsx)(n.p,{children:"In areas where three planes overlap their power gets more intense at the center where their is the most overlap. Creating a strong Elemental Nexus that is a condensed generator powering the plane around it."}),"\n",(0,i.jsx)(n.h3,{id:"earth-air-and-fire-overlap-solar-radiant-weak-force",children:"Earth, Air, and Fire Overlap (Solar, radiant, weak force):"}),"\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsxs)(n.li,{children:["\n",(0,i.jsx)(n.p,{children:'(+) Crystalline Skies: This realm is a wondrous fusion of earth, air, and fire elements. It features floating crystal mountains, radiant geysers of molten gemstones, and swirling currents of magical winds. Inhabitants are graceful crystal beings that harness the power of these elements for creation and art. In particular, the weak force can change one quark type into another. Protons and neutrons are made of two quark varieties, up and down. The weak force can turn a down quark in a neutron into an up quark, which would change the neutron into a proton and switch its electric charge from neutral to positive. If that neutron were in the nucleus of an atom, the change to a proton would turn that atom into a different type of element. Such reactions are happening all the time in our Sun, giving it the energy to shine. This type of action also occurs in radioactive decay, which happens when atoms spontaneously shed energy and subatomic particles. So earth and fire  combine into lava and metallic volcanic rock are whisked away with the forces of magnetism but when the three combine into a "Solar bubble" the bubble of radiance is the first sign of this odd force.'}),"\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsx)(n.li,{children:"At its center: In the mystical heart of the multiverse, hidden from the realm of matter and energy as we know it, lies the enigmatic Wyrdflux Confluence\u2014a plane born from the obscure and elusive forces of the weak nuclear interaction. Here, the fabric of reality is woven from the most delicate and elusive threads, giving rise to a world of subatomic sorcery and profound mystery."}),"\n",(0,i.jsx)(n.li,{children:"Description: The Confluence is a realm shrouded in shimmering, ephemeral veils of energy. The very air quivers with the whisper of subatomic particles, and the entire environment seems to fluctuate and oscillate as if subject to the subtle rhythms of the weak force. Colors here are strange and otherworldly, and the laws of physics and magic are unlike anything experienced in the mundane realms."}),"\n",(0,i.jsxs)(n.li,{children:["Landscapes:","\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsx)(n.li,{children:"The Lattice Expanse: The landscape of the Wyrdflux Confluence is a lattice-like network of crystalline structures, composed of quarks and leptons. These structures pulse with a rhythmic, iridescent glow, and they can be rearranged by those who understand the principles of subatomic manipulation."}),"\n",(0,i.jsx)(n.li,{children:"Quantum Oases: Scattered throughout the plane are quantum oases, where pools of liquid particles drift in the air. These oases grant unique abilities when touched, allowing individuals to temporarily transcend the boundaries of classical reality."}),"\n",(0,i.jsx)(n.li,{children:"Electroweak Forests: The forests in this plane consist of ethereal trees that sway with the ephemeral breeze of the weak interaction. These forests are the home to beings that exist at the subatomic level, embodying the principles of the weak force in their very essence."}),"\n"]}),"\n"]}),"\n",(0,i.jsxs)(n.li,{children:["Inhabitants: The inhabitants of the Wyrdflux Confluence are creatures of subatomic nature, beings who manipulate the forces of the weak interaction, and scholars of subatomic sorcery. They include:","\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsx)(n.li,{children:"Wispquarks: These ephemeral beings are born of the very fabric of the plane and possess the power to phase in and out of existence, allowing them to traverse the delicate lattice structures and quantum oases with ease."}),"\n",(0,i.jsx)(n.li,{children:'Quantum Archmages ("Quantumaniacs"): Scholars and practitioners of subatomic sorcery, quantum archmages have mastered the manipulation of the weak force, granting them the ability to reshape the very world around them.'}),"\n",(0,i.jsx)(n.li,{children:"Chromomagisters: These beings harness the strong nuclear force to bend and twist the lattice structures to their will, often wielding the hidden secrets of gluon magic."}),"\n",(0,i.jsx)(n.li,{children:"Quark Beasts: These creatures are made up of quarks and leptons and can manipulate the subatomic structures of the Wyrdflux Confluence to their advantage. They are often found near the crystalline structures of The Lattice Expanse."}),"\n",(0,i.jsx)(n.li,{children:"Radiant Geysersaur: This creature is a dinosaur-like being that feeds on the molten gemstones that spew from the radiant geysers of the Crystalline Skies. It has a shimmering, iridescent hide that reflects the strange and otherworldly colors of this plane."}),"\n",(0,i.jsx)(n.li,{children:"Ephemeral Whisp: This creature is a wispy, ethereal being that flits through the shimmering veils of energy that shroud the Wyrdflux Confluence."}),"\n"]}),"\n"]}),"\n",(0,i.jsx)(n.li,{children:"Powers and Magic: In the Wyrdflux Confluence, magic is closely intertwined with the principles of subatomic particles and the manipulation of the weak force. Visitors to this plane may gain the ability to manipulate quantum states, alter the fundamental constants of the universe, and harness the powers of particles at the subatomic level."}),"\n",(0,i.jsx)(n.li,{children:"Purpose and Quests: The Wyrdflux Confluence is a realm of experimentation and enlightenment. Those who journey to this plane seek to unlock the mysteries of the subatomic universe, master the manipulation of the weak interaction, and discover the secrets of particle-based magic. Quests often revolve around deciphering the intricacies of subatomic sorcery and understanding the profound connections between matter and energy at the smallest scales. The Wyrdflux Confluence is a plane where the very essence of reality is woven from the threads of the weak nuclear force. It offers a world of subatomic wonders, mysteries, and limitless potential, attracting seekers of knowledge and explorers of the most fundamental forces in the cosmos."}),"\n"]}),"\n"]}),"\n",(0,i.jsxs)(n.li,{children:["\n",(0,i.jsx)(n.p,{children:"(-) Eruptive Tempest: Eruptive Tempest is a volatile and chaotic world filled with erupting volcanoes, tumultuous tornadoes of molten rock, and fiery hurricanes. The environment is treacherous, inhabited by destructive elemental entities, and the land itself is constantly in flux."}),"\n"]}),"\n"]}),"\n",(0,i.jsx)(n.h3,{id:"earth-air-and-water-overlap-gravity",children:"Earth, Air, and Water Overlap (Gravity):"}),"\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsxs)(n.li,{children:["\n",(0,i.jsx)(n.p,{children:"(+) Ethereal Gardens: Ethereal Gardens is a paradise of floating islands adorned with lush, hanging gardens and crystal-clear waterfalls. The harmony of earth, air, and water allows for vibrant flora and serene aquatic life to flourish. Inhabitants are elemental gardeners and caretakers of this magical realm."}),"\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsx)(n.li,{children:"The Graviflow Nexus at the center of the Plane of Gravity: In the ever-expanding multiverse, concealed beyond the boundaries of known reality, lies the enigmatic Graviflow Nexus\u2014a plane uniquely tethered to the fundamental force of gravity. Here, the intricate dance between earth, air, and water intertwines with the gravitational pull of celestial bodies, giving rise to a world of astonishing marvels and perilous depths."}),"\n",(0,i.jsx)(n.li,{children:"Description: The Graviflow Nexus is a realm where the essence of gravity itself weaves a tapestry of perpetual change. The very air is thick with potential, and the landscape is molded by the ceaseless ebb and flow of gravitational forces. Here, nature's rules are constantly rewritten, and travelers must navigate this ever-shifting environment to uncover its mysteries."}),"\n",(0,i.jsxs)(n.li,{children:["Landscapes:","\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsx)(n.li,{children:"Aetherial Chasms: The Graviflow Nexus is a realm of immense, floating landmasses that defy conventional gravitational expectations. These floating islands, often covered in lush forests and interconnected by breathtaking bridges, hover in the skies, making for a breathtaking sight."}),"\n",(0,i.jsx)(n.li,{children:"Tidal Moonscapes: Within the realm, you'll find vast tidal pools, remnants of the ebb and flow of gravitational forces. These pools mirror the phases of celestial bodies and harbor unique ecosystems that flourish with the shifting gravitational tides."}),"\n",(0,i.jsx)(n.li,{children:"Abyssal Siphon: Beneath the floating islands, a dark and enigmatic abyss beckons. The depths are a confluence of gravitationally bound waters, teeming with eerie bioluminescent creatures and secrets that lure explorers into its depths."}),"\n"]}),"\n"]}),"\n",(0,i.jsxs)(n.li,{children:["Inhabitants: The Graviflow Nexus is inhabited by beings that have adapted to the ever-changing forces of gravity, showcasing unique abilities and powers:","\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsx)(n.li,{children:"Skytreaders: Skytreaders are the natives of the floating islands, and they move with elegance through the ever-shifting terrain. They have an innate connection to the gravitational fields, allowing them to traverse the landscape with grace."}),"\n",(0,i.jsx)(n.li,{children:"Tidal Drifters: Tidal Drifters are aquatic beings that dwell in the tidal pools, adept at navigating the gravitational flux and providing insights into the realm's intricate tides."}),"\n",(0,i.jsxs)(n.li,{children:["Abyssal Nomads: These enigmatic creatures inhabit the abyssal depths and have evolved to withstand the gravitational extremes below. Their knowledge of the abyssal secrets is sought after by daring explorers. ",(0,i.jsx)(n.a,{href:"https://5e.tools/bestiary.html#nafas_qftis",children:"https://5e.tools/bestiary.html#nafas_qftis"})]}),"\n"]}),"\n"]}),"\n",(0,i.jsxs)(n.li,{children:["Encounters","\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsx)(n.li,{children:"Flying whales that suck in food via gravity they are bigger than dragons like literal blue whale"}),"\n",(0,i.jsx)(n.li,{children:"All gravity creatures should have the ability to reflect spell energy as well"}),"\n",(0,i.jsx)(n.li,{children:"And all creatures are natural gravitational surgebinders"}),"\n"]}),"\n"]}),"\n",(0,i.jsxs)(n.li,{children:["Powers and Magic:","\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsx)(n.li,{children:"Visitors to the Graviflow Nexus may harness the elemental forces of earth, air, and water and gain the ability to manipulate gravity to a degree. They can control the ebb and flow of gravitational forces or even alter the direction of gravity within limited areas, granting them unique powers within the realm."}),"\n"]}),"\n"]}),"\n",(0,i.jsx)(n.li,{children:"Purpose and Quests:"}),"\n",(0,i.jsx)(n.li,{children:"Journeys to the Graviflow Nexus often revolve around unlocking the secrets of the gravitational forces and the elemental convergence of earth, air, and water. Travelers may seek to understand the patterns of gravity within the realm, uncover the mysteries of the abyssal depths, or uncover the hidden powers of the celestial bodies that influence this extraordinary realm."}),"\n",(0,i.jsx)(n.li,{children:"The Graviflow Nexus is a realm of dynamic equilibrium where the forces of gravity are a constant, guiding influence. Its surreal landscapes, extraordinary inhabitants, and remarkable magical properties make it a realm of perpetual wonder and danger, drawing explorers and scientists alike to uncover its enigmatic secrets."}),"\n"]}),"\n"]}),"\n",(0,i.jsxs)(n.li,{children:["\n",(0,i.jsx)(n.p,{children:"(-) Tempestual Abyss: Tempestual Abyss is a tumultuous expanse of stormy seas, massive water spouts, and jagged rock formations. The combination of these elements creates a hazardous environment inhabited by monstrous sea and storm creatures."}),"\n"]}),"\n"]}),"\n",(0,i.jsx)(n.h3,{id:"earth-fire-and-water-overlap-lunar-strong-force-",children:"Earth, Fire, and Water Overlap (Lunar, Strong Force) :"}),"\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsxs)(n.li,{children:["\n",(0,i.jsx)(n.p,{children:"(+) Geothermal Oasis: Geothermal Oasis is a realm where bubbling hot springs, steamy geysers, and fertile volcanic soil create a unique and thriving ecosystem. Earth, fire, and water live in harmony, giving rise to vibrant plant life and aquatic creatures. Inhabitants are skilled geothermancers who use the fusion of these elements for healing and growth."}),"\n"]}),"\n",(0,i.jsxs)(n.li,{children:["\n",(0,i.jsx)(n.p,{children:"(-) Molten Abyss: Molten Abyss is a nightmarish world of perpetual eruptions, magma oceans, and scalding steam clouds. The environment is treacherous, inhabited by fire demons, monstrous sea creatures, and destructive water elementals."}),"\n"]}),"\n"]}),"\n",(0,i.jsx)(n.h3,{id:"air-fire-and-water-overlap-electromagnetic",children:"Air, Fire, and Water Overlap (electromagnetic):"}),"\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsxs)(n.li,{children:["\n",(0,i.jsx)(n.p,{children:"(+) Elemental Convergence: Elemental Convergence is a breathtaking realm where fire dances on the water's surface, and steam rises into the air. The combination of air, fire, and water creates an environment of beauty and balance. Inhabitants are diverse, including aquatic firebirds and serene mistweavers who maintain harmony in this realm."}),"\n"]}),"\n",(0,i.jsxs)(n.li,{children:["\n",(0,i.jsx)(n.p,{children:"(-) Infernal Deluge: Infernal Deluge is a plane of unending torment, where blistering fire rains down from the sky into roiling, boiling seas. The atmosphere is choked with ash and steam, and it's a place of suffering and destruction, inhabited by nightmarish creatures of fire, water, and air."}),"\n"]}),"\n"]}),"\n",(0,i.jsx)(n.h2,{id:"pandemonium",children:"Pandemonium"}),"\n",(0,i.jsx)(n.p,{children:"The poles are the ends of a massive core known as the Pandemonium stone."}),"\n",(0,i.jsx)(n.h3,{id:"the-luminous-nexus---plane-of-elemental-harmony-apex-pandemonium-time-ether",children:"The Luminous Nexus - Plane of Elemental Harmony, Apex Pandemonium (Time, Ether)"}),"\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsx)(n.li,{children:"Description: The Luminous Nexus is a realm of ethereal beauty and profound tranquility. The atmosphere is bathed in an otherworldly, gentle radiance, where the very air sparkles with a silvery luminescence. A sense of serenity envelops everything, and the harmonious union of the elements and positive energy infuse the landscape with an aura of life and vitality. This is a place where the four overlaping elements of earth, air, fire, and water exist in a state of harmony. Calm cycles from one to the next create serene landscapes and a feeling of peace."}),"\n",(0,i.jsxs)(n.li,{children:["Landscapes:","\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsx)(n.li,{children:"Crystalline Mountains: The land is adorned with immense, crystalline mountains that appear to be sculpted from precious gems. These mountains exude a soothing, warm light and are home to luminous flora that seem to feed on the radiant energy that permeates the terrain."}),"\n",(0,i.jsx)(n.li,{children:"Ethereal Oceans: Vast, ethereal oceans stretch beyond the horizon. The water is crystal clear and shimmers with a gentle inner glow. Here, beings of both elemental and positive energy coexist peacefully, creating a unique and diverse underwater ecosystem."}),"\n",(0,i.jsx)(n.li,{children:"Sky Gardens: Floating islands, suspended in the sky, serve as lush, floating gardens. These islands are adorned with vibrant, semi-translucent flora that thrives on the harmonious blend of air and positive energy. Their blooming flowers and radiant trees provide shelter to celestial creatures and elemental beings alike."}),"\n"]}),"\n"]}),"\n",(0,i.jsxs)(n.li,{children:["Inhabitants:","\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsx)(n.li,{children:"The inhabitants of the Luminous Nexus are a harmonious mix of beings who embody the principles of unity and balance. They include:"}),"\n",(0,i.jsx)(n.li,{children:"Luminari: Luminari are radiant beings of pure energy, composed of the elements and the positive energy plane. They act as caretakers of the Nexus, ensuring the equilibrium of the realm and offering guidance to those who seek it."}),"\n",(0,i.jsx)(n.li,{children:"Elemental Sentinels: Elemental beings from each of the classical elements call the Luminous Nexus home. They have found a way to coexist peacefully in this plane, transcending their traditional elemental conflicts."}),"\n",(0,i.jsx)(n.li,{children:"Celestial Guardians: Angelic beings and celestial creatures find solace in the Luminous Nexus, serving as protectors of this unique plane. They watch over the harmonious balance and offer their wisdom to visitors."}),"\n",(0,i.jsx)(n.li,{children:"Radiant Stags: These graceful creatures are similar to deer, but their antlers are made of pure light. They are often found grazing in the meadows of the Luminous Nexus."}),"\n",(0,i.jsx)(n.li,{children:"White lions: These creatures heavily resemble lions but they have pure white fur and four eyes each a different color (red, white, blue, brown). They seemingly fight with radiance itself."}),"\n",(0,i.jsx)(n.li,{children:"Radiant Dragons"}),"\n",(0,i.jsx)(n.li,{children:"Harmony Spirits: These ethereal beings embody the harmonious union of the elements and positive energy that infuse the landscape of the Luminous Nexus. They can often be seen dancing in the silvery luminescence of the atmosphere."}),"\n"]}),"\n"]}),"\n",(0,i.jsxs)(n.li,{children:["Powers and Magic:","\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsx)(n.li,{children:"The Luminous Nexus is a wellspring of magical energy. Visitors to this plane can tap into the elemental forces and the life-giving energy of the Positive Energy Plane. It is a place where the boundaries between reality and the metaphysical are blurred, and where those with pure hearts can manifest their desires and intentions with ease."}),"\n"]}),"\n"]}),"\n",(0,i.jsxs)(n.li,{children:["Purpose and Quests:","\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsx)(n.li,{children:"The Luminous Nexus is said to hold the key to understanding the deepest secrets of elemental mastery and the harnessing of positive energy. Those who seek enlightenment, spiritual growth, or the power to heal and create are drawn to this plane. Quests within the Nexus often involve exploring the balance of the elements and discovering one's inner harmony."}),"\n",(0,i.jsx)(n.li,{children:"The Luminous Nexus is a realm of awe-inspiring beauty, where the convergence of the four classical elements and the positive energy plane creates a haven of balance and enlightenment. Its landscapes, inhabitants, and magical properties make it a place of profound significance in the Elemental Energy Plane, drawing seekers and adventurers from across the multiverse."}),"\n"]}),"\n"]}),"\n"]}),"\n",(0,i.jsx)(n.h3,{id:"the-abyssal-crucible---plane-of-elemental-discord-void-ether-deep-pandemonium",children:"The Abyssal Crucible - Plane of Elemental Discord (Void, ether) Deep Pandemonium"}),"\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsx)(n.li,{children:"Description: The Abyssal Crucible is a place of perpetual turmoil and darkness, where the very air feels heavy with dread. The twisted fusion of elemental forces and negative energy permeates the landscape with an unsettling aura of desolation and destruction. The four pure elements seemingly fight eachother in a state of pure chaos."}),"\n",(0,i.jsxs)(n.li,{children:["Landscapes:","\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsx)(n.li,{children:"Volcanic Wastes: Jagged and seething, the land of the Abyssal Crucible is dominated by immense volcanoes that spew forth molten rock and rivers of shadowy, corrosive ooze. The very earth is cracked and crumbling, revealing a core of dark, pulsating energy."}),"\n",(0,i.jsx)(n.li,{children:"Eternal Tempests: Furious, eternal storms rage overhead, with lightning that courses through the ashen skies. Tornadoes and cyclones of malevolent winds tear across the landscape, further perpetuating the discordant forces that reign here."}),"\n",(0,i.jsx)(n.li,{children:"Cursed Waters: Twisted, inky-black seas stretch to the horizon, harboring monstrous, spectral creatures that feed on the unholy union of water and negative energy. The waves crash with a malevolent intent, their brackish spray inflicting despair and decay. The water is somehow boiling hot and stings with a current of electricity."}),"\n"]}),"\n"]}),"\n",(0,i.jsxs)(n.li,{children:["Inhabitants: The inhabitants of the Abyssal Crucible are a grotesque mix of corrupted beings who thrive on chaos and discord. They include:","\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsx)(n.li,{children:"Shadowfiends: These abhorrent entities are born from the darkest intersections of the elements and negative energy. They are sinister, shape-shifting creatures that revel in confusion and chaos."}),"\n",(0,i.jsx)(n.li,{children:"Twisted Elementals: Elemental creatures in the Abyssal Crucible have been corrupted by the malevolent energies, taking on grotesque and destructive forms that exist to perpetuate discord."}),"\n",(0,i.jsx)(n.li,{children:"Spectral Aberrations: Ghostly and malicious spirits, drawn to the negative energy, haunt this plane. They torment travelers with sinister illusions and haunting apparitions."}),"\n"]}),"\n"]}),"\n",(0,i.jsxs)(n.li,{children:["Powers and Magic:","\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsx)(n.li,{children:"The Abyssal Crucible is a wellspring of dark and chaotic magic. Visitors to this plane may be granted powers that manipulate destruction and entropy, but at a great cost to their own well-being and sanity. The plane itself seems to conspire against any who enter, twisting their thoughts and desires to suit its malevolent agenda."}),"\n"]}),"\n"]}),"\n",(0,i.jsxs)(n.li,{children:["Purpose and Quests:","\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsx)(n.li,{children:"The Abyssal Crucible is a place of torment and peril. Travelers who find themselves within its borders may be driven by dark ambitions, seeking power or chaos. Quests in the Abyssal Crucible often involve unraveling the mysteries of the elemental chaos, battling the malevolent beings that dwell here, or attempting to harness the corrupting forces for their own purposes."}),"\n",(0,i.jsx)(n.li,{children:"The Abyssal Crucible is a realm of nightmarish despair, where the convergence of the four classical elements and the negative energy plane creates a place of unending discord and torment. Its landscapes, inhabitants, and magical properties make it a perilous destination in the Elemental Energy Plane, drawing only the most twisted and power-hungry beings who dare to traverse its treacherous terrain."}),"\n"]}),"\n"]}),"\n"]})]})}function c(e={}){let{wrapper:n}={...(0,r.R)(),...e.components};return n?(0,i.jsx)(n,{...e,children:(0,i.jsx)(d,{...e})}):d(e)}},8453(e,n,a){a.d(n,{R:()=>s,x:()=>l});var t=a(6540);let i={},r=t.createContext(i);function s(e){let n=t.useContext(r);return t.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function l(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:s(e.components),t.createElement(r.Provider,{value:n},e.children)}}}]);